items.outputText:
{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 병목에 맞는 개선 방법을 선택한 기준을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "운영 화면의 조회 쿼리가 느려 성능 개선이 필요했던 상황이다.",
          "task": "확인된 병목에 적합한 개선 방법을 정하는 것이 본인의 과제였다.",
          "action": "실행 계획이나 로그에서 확인한 병목을 바탕으로 개선 방법의 적합성을 판단하고, 효과를 비교할 측정 기준을 정한 내용이 드러난다.",
          "result": "비교 가능한 조건에서 측정한 개선 전후 수치로 선택한 방법의 효과를 확인한 내용이 드러난다."
        },
        "expectedEvidence": [
          "개선 방법을 선택하는 기준으로 사용한 실행 계획이나 로그상의 병목 징후",
          "확인한 병목과 선택한 개선 방법 사이의 연결 관계",
          "선택한 방법의 효과를 판단하는 데 사용한 개선 전후 측정 기준"
        ]
      },
      "question": "운영 화면의 신고 목록 조회 쿼리를 개선하셨다고 했는데요. 어떤 기준으로 쿼리의 성능 개선 방법을 정하셨나요?",
      "answerTip": "당시 본인이 판단한 내용을 중심으로 차분하게 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획이나 로그에서 확인한 병목 징후를 개선 방법의 선택 기준으로 제시한다.",
            "선택한 방법이 해당 병목을 줄일 수 있는 이유를 연결해 설명한다.",
            "비교 가능한 측정 조건과 개선 전후 수치를 제시해 선택 기준의 타당성을 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "병목에 근거한 개선 방법의 선택 기준은 제시하지만, 관찰한 징후나 방법과의 연결 설명이 일부 부족하다.",
            "효과를 판단할 측정 기준은 언급하지만, 비교 조건이나 개선 전후 수치가 충분하지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "병목에 대한 근거 없이 익숙하거나 일반적으로 빠르다는 이유만으로 개선 방법을 선택했다고 답한다.",
            "적용한 기술이나 성과 수치만 나열하고, 개선 방법을 정한 기준과 효과 판단 기준을 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "배포 후 발생한 오류의 원인을 좁힐 때 사용한 로그와 관측 사실의 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "배포 후 알림이 중복 발송되어 오류 원인을 확인해야 했던 상황이다.",
          "task": "본인이 확인할 수 있는 로그를 바탕으로 중복 발송의 원인을 좁히는 것이 과제였다.",
          "action": "발생 시각과 실행 주체 등 관련 로그를 대조하고, 관측한 사실이 특정 원인을 뒷받침하는 이유를 설명한다.",
          "result": "원인에 맞춘 조치 이후 동일 증상의 발생 여부를 확인해 원인 판단을 검증한 내용이 드러난다."
        },
        "expectedEvidence": [
          "중복 발송과 관련해 대조한 로그의 구체적인 정보",
          "로그에서 관측한 사실이 추정 원인을 뒷받침하는 연결 관계",
          "조치 이후 동일 증상의 발생 여부로 원인 판단을 검증한 근거"
        ]
      },
      "question": "배포 후 알림 중복 발송 오류를 로그로 추적하셨다고 했는데요. 무엇을 근거로 알림 중복 발송의 원인을 좁히셨나요?",
      "answerTip": "기억나는 사실과 본인의 추측을 구분해서 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "발생 시각이나 실행 주체 등 실제로 대조한 로그 정보를 제시한다.",
            "로그의 관측 사실이 추정 원인을 뒷받침하는 이유를 설명해 단순한 추측과 구분한다.",
            "원인에 맞춘 조치 이후 같은 증상의 발생 여부를 확인한 결과로 원인 판단을 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "확인한 로그 정보와 원인 사이의 연결은 설명하지만, 대조한 정보나 추론의 구체성이 일부 부족하다.",
            "원인을 좁힌 근거는 있으나, 조치 이후 동일 증상 여부를 확인한 내용이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "로그를 확인했다고만 말하고 원인을 뒷받침한 관측 사실을 제시하지 못한다.",
            "수정 방법이나 최종 원인만 말하고, 해당 원인으로 좁힌 근거를 설명하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "요구사항을 정의할 때 어떤 기준으로 포함할 기능과 제외할 기능의 범위를 정했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "서비스 기획에서 수집한 요청을 요구사항으로 구체화하며 기능의 포함 여부를 판단해야 했던 상황이다.",
          "task": "요청의 목적에 맞게 구현할 기능의 범위를 정하는 것이다.",
          "action": "해결할 문제와의 관련성, 요청 간 우선순위, 구현 가능한 범위를 기준으로 기능의 포함 여부를 판단한다.",
          "result": "판단 기준에 따라 포함하거나 제외한 기능이 요구사항에 구분되어 개발·디자인 담당자와 논의할 범위가 명확해진다."
        },
        "expectedEvidence": [
          "요청이 해결하려는 문제나 목적을 기능의 포함 여부와 연결한 기준",
          "요청 간 우선순위와 구현 가능한 범위를 고려한 포함·제외 기준",
          "제시한 기준을 실제 기능의 포함 또는 제외 판단에 적용한 내용"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획을 하셨다고 했는데요. 어떤 기준으로 요구사항에 넣을 기능의 범위를 정하셨나요?",
      "answerTip": "당시의 한 장면을 떠올리며 본인이 판단한 내용을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "해결할 문제나 목적에 비추어 어떤 기능이 필요한지 판단한 기준을 설명한다.",
            "요청 간 우선순위와 구현 가능한 범위를 포함·제외 판단에 적용한 내용을 설명한다.",
            "그 기준으로 포함하거나 제외한 기능을 짚어 요구사항의 범위가 명확해진 결과를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "기능을 포함하거나 제외한 기준을 요청의 목적, 우선순위 또는 구현 가능한 범위와 연결해 설명한다.",
            "다만 기준을 실제 기능에 적용한 내용이나 그에 따라 정해진 요구사항 범위가 일부 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "요청을 수집하거나 문서를 작성했다는 설명에 그쳐 기능의 포함·제외 기준이 드러나지 않는다.",
            "기능 목록이나 도구 사용법만 설명하며 요구사항 범위를 판단한 내용은 제시하지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "화면설계에서 어떤 기준으로 각 화면에 명시할 예외 상황을 선정했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "기능 흐름을 화면설계서로 구체화하면서 정상 흐름 외의 상황을 정리해야 했던 상황이다.",
          "task": "각 화면에서 별도로 설계해야 하는 예외 상황을 선정하는 것이다.",
          "action": "정상 흐름에서 벗어나는 조건이 화면 상태, 가능한 사용자 행동, 안내 문구에 차이를 만드는지를 기준으로 예외 상황을 선정한다.",
          "result": "선정한 예외 상황이 화면설계서에 반영되어 해당 조건에서 보여줄 화면과 안내가 명확해진다."
        },
        "expectedEvidence": [
          "정상 흐름에서 벗어나는 발생 조건을 예외 상황 선정 기준으로 삼은 내용",
          "화면 상태나 사용자 행동, 안내 문구가 달라지는지를 고려한 선정 기준",
          "제시한 기준에 따라 화면설계서에 담은 구체적인 예외 상황"
        ]
      },
      "question": "화면설계서 28장을 작성하셨다고 했는데요. 각 화면에 별도로 담아야 할 예외 상황은 어떤 기준으로 정하셨나요?",
      "answerTip": "기억나는 한 장면을 중심으로 본인이 생각했던 내용을 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "정상 흐름에서 벗어나는 발생 조건을 구체적으로 구분해 예외 상황의 선정 기준을 설명한다.",
            "그 조건이 화면 상태나 사용자 행동, 안내 문구에 만드는 차이를 선정 이유와 연결한다.",
            "해당 기준으로 선정한 예외 상황과 화면설계서에 명시된 내용을 짚어 화면의 동작이나 안내가 명확해진 결과를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "정상 흐름과 다른 조건이나 화면에 별도 표현이 필요한 차이를 기준으로 예외 상황을 선정했다고 설명한다.",
            "다만 선정 기준의 구체성, 실제 예외 상황에 적용한 내용 또는 화면설계서에 반영된 결과 중 일부가 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황을 고려했다는 말이나 예외 목록만 제시하고 선정 기준을 설명하지 않는다.",
            "화면의 배치나 디자인 도구 사용법만 설명하며 예외 조건에 따른 화면 설계 판단은 드러내지 않는다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "의심스러운 진통제 처방에 대해 투약 여부를 판단한 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어온 상황이다.",
          "task": "처방의 정확성이 확인되지 않은 상태에서 투약해도 되는지 판단해야 했다.",
          "action": "처방 용량을 기존 투약 내용이나 환자에게 적용되는 용량 정보와 대조하고, 불일치가 해소되지 않아 투약을 보류했다. 담당의의 확인 내용을 근거로 이후 투약 여부를 판단했다.",
          "result": "담당의 확인을 통해 입력 오류가 드러났으며, 잘못된 용량이 투여되는 것을 막았다."
        },
        "expectedEvidence": [
          "처방 용량에 의문을 가진 이유를 실제 대조한 정보와 연결해 설명한다.",
          "처방의 정확성이 확인되지 않았다는 점을 투약 보류의 근거로 제시한다.",
          "담당의에게 확인한 내용을 이후 투약 여부의 판단 근거로 제시한다."
        ]
      },
      "question": "수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어온 적이 있다고 하셨는데요. 당시 투약 여부는 무엇을 근거로 판단하셨나요?",
      "answerTip": "당시 상황을 떠올리며 본인이 했던 일을 중심으로 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "처방 용량을 무엇과 대조했는지 밝히고, 그 차이가 처방 확인을 필요로 했던 이유를 설명한다.",
            "확인 전 투약 보류와 담당의 확인 후 판단의 근거를 구분해 설명하며, 입력 오류 확인으로 잘못된 투약을 막은 결과까지 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소와 다른 용량을 근거로 투약을 보류하고 담당의에게 확인했다고 설명한다.",
            "다만 실제 대조한 정보, 담당의의 확인 내용 또는 확인 이후의 결과가 일부 불명확하다."
          ]
        },
        "poor": {
          "criteria": [
            "투약 여부를 판단한 근거 없이 주의해서 투약한다는 일반적인 원칙만 말한다.",
            "의심스러운 처방을 확인하지 않고 그대로 투약하거나, 담당의 확인 없이 임의로 용량을 바꾼다고 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자의 의식 수준 저하를 발견했을 때 상태 확인을 기록, 담당 의사 보고, 다음 근무자 인수인계로 연결하는 조치의 순서를 확인한다.",
        "questionType": "situational",
        "expectedSTAR": {
